        stream = new SimpleCharStream(new StringReader("ABC"));

        char c1 = stream.BeginToken();
        assertEquals('A', c1);
        assertEquals(0, stream.tokenBegin);

        char c2 = stream.BeginToken();
        assertEquals('B', c2);
        assertEquals(1, stream.tokenBegin);

