            fail("Expected IOException to be thrown");
        } catch (IOException e) {
            // Expected behavior for empty stream
        }
    }

    @Test
    public void testBeginTokenUpdatesLineAndColumn() throws IOException {
        stream = new SimpleCharStream(new StringReader("A\nB"));

        stream.BeginToken();
        assertEquals(1, stream.line);
        assertEquals(1, stream.column);

        stream.BeginToken();
        assertEquals(2, stream.line);
        assertEquals(1, stream.column);

        stream.BeginToken();
        assertEquals(2, stream.line);
        assertEquals(2, stream.column);
    }

    @Test
    public void testBeginTokenWithSpecialCharacters() throws IOException {
        stream = new SimpleCharStream(new StringReader("\r\t"));

        char c1 = stream.BeginToken();
        assertEquals('\r', c1);
        assertEquals(0, stream.tokenBegin);

        char c2 = stream.BeginToken();
        assertEquals('\t', c2);
        assertEquals(1, stream.tokenBegin);
    }
}

